function scan(url){
  url=(url||'').trim(); var flags=[]; var score=0;
  if(!/^https?:\/\//i.test(url)){ flags.push('缺少 http(s) 协议'); score+=1; }
  else if(/^http:\/\//i.test(url)){ flags.push('使用明文 http 而非 https'); score+=1; }
  if(url.indexOf('@')>=0){ flags.push('URL 含 @（易混淆主机）'); score+=2; }
  var host=url.replace(/^https?:\/\//i,'').split('/')[0];
  if(/^\d{1,3}(\.\d{1,3}){3}$/.test(host)){ flags.push('使用 IP 地址而非域名'); score+=2; }
  var dots=(host.match(/\./g)||[]).length; if(dots>=4){ flags.push('子域过多('+dots+'个.)'); score+=1; }
  var susp=/login|signin|verify|bank|paypal|account|password|secure|update|ebay/i;
  if(susp.test(url)){ flags.push('含敏感词('+(url.match(susp)||[])[0]+')'); score+=1; }
  if(/\.tk$|\.ml$|\.ga$|\.cf$|\.gq$/i.test(host)){ flags.push('免费短命域名后缀'); score+=1; }
  var valid = /^https?:\/\/[^\s/$.?#].[^\s]*$/i.test(url);
  return {url:url, valid:valid, flags:flags, score:score, risk: score>=3?'高':(score>=1?'中':'低')};
}
var EXPORTS={scan:scan};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.UrlScanForgePure = EXPORTS; }
